import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(0)
        return

    n = int(data[0])

    if n == 0:
        print(0)
        return

    cost = []
    index = 1
    for i in range(n):
        row = list(map(int, data[index:index + n]))
        cost.append(row)
        index += n

    total_masks = 1 << n
    dp = [float('inf')] * total_masks
    dp[0] = 0

    for mask in range(total_masks):
        task = bin(mask).count('1')
        if task >= n:
            continue
        for person in range(n):
            if not (mask & (1 << person)):
                new_mask = mask | (1 << person)
                dp[new_mask] = min(dp[new_mask], dp[mask] + cost[task][person])

    print(dp[total_masks - 1])

if __name__ == "__main__":
    main()
